BigInteger prev = BigInteger.ZERO;
BigInteger curr = BigInteger.ONE;
for (int i = 2; i <= 100; i++) {
    BigInteger next = prev.add(curr);
    prev = curr;
    curr = next;
}
System.out.println("100. liczba Fibonacciego: " + curr);

