int scale = 25;
BigDecimal sum = BigDecimal.ZERO;
BigDecimal four = BigDecimal.valueOf(4);
for (int i = 0; i < 10000; i++) {
    BigDecimal term = BigDecimal.ONE.divide(BigDecimal.valueOf(2L * i + 1), scale, RoundingMode.HALF_UP);
    if (i % 2 == 0) {
        sum = sum.add(term);
    } else {
        sum = sum.subtract(term);
    }
}
BigDecimal piApprox = sum.multiply(four);
System.out.println("Aproksymacja pi: " + piApprox);

BigDecimal P = new BigDecimal("500000.00");
BigDecimal r = new BigDecimal("0.065").divide(BigDecimal.valueOf(12), 10, RoundingMode.HALF_UP);
int n = 360;
BigDecimal onePlusR = BigDecimal.ONE.add(r);
BigDecimal onePlusRPowN = onePlusR.pow(n);
BigDecimal numerator = P.multiply(r).multiply(onePlusRPowN);
BigDecimal denominator = onePlusRPowN.subtract(BigDecimal.ONE);
BigDecimal payment = numerator.divide(denominator, 2, RoundingMode.HALF_UP);
System.out.println("Miesieczna rata: " + payment);

